"""Materialize four exact original-PCM audition inputs and a credit proposal.
No speech requests, production rows or source approvals.
"""
import json,hashlib,subprocess,wave,math,re,sqlite3,html,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parent;BASE=ROOT.parent
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,d):p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
packet=read(BASE/'source-packet-v3/source-packet.json')
for k,p in [('hatam',packet['input']['hatam']),('reference',packet['input']['english']),('audio',packet['input']['audio'])]:assert sha(Path(p))==packet['input']['sourceHashes'][k]
initial=read(ROOT/'candidate-quotes.json');corrected=read(ROOT/'recheck-candidates.json');tail=read(ROOT/'final-tail-candidate.json')
audits={}
for folder in ['boundary-audit','boundary-recheck','final-tail-audit']:
 j=read(ROOT/folder/'execution.json');assert j['status']=='completed_provisional' and j['pendingUpperBoundUsd']==0
 for c in j['calls']:audits[c['id']]={'journal':folder+'/execution.json','call':c}
chosen={t['id']:t for t in initial['tests']}
chosen.update({t['id']:t for t in corrected['tests']});chosen.update({t['id']:t for t in tail['tests']})
normalize=lambda s:' '.join(re.sub(r'[^\w]+',' ',s.lower()).split())
for key,t in chosen.items():
 a=audits[key]['call'];r=a['result'];assert a['candidateStartMs']==t['startMs'] and a['candidateEndMs']==t['endMs']
 assert r['headVerdict']=='complete_word' and r['tailVerdict']=='complete_word' and r['candidateContainsFullQuote'] is True and r['candidateContainsOtherWords'] is False
 assert normalize(r['heardWordsInsideCandidate'])==normalize(t['quote'])
source=Path(packet['input']['audio']);info=json.loads(subprocess.check_output(['ffprobe','-v','error','-select_streams','a:0','-show_streams','-of','json',str(source)],creationflags=subprocess.CREATE_NO_WINDOW))['streams'][0];assert int(info['sample_rate'])==24000 and int(info['channels'])==2
pcm=subprocess.check_output(['ffmpeg','-v','error','-nostdin','-i',str(source),'-map','0:a:0','-f','s16le','-'],creationflags=subprocess.CREATE_NO_WINDOW)
assigned=read(BASE/'canon-package-v1/voice-assignment-receipt.json')['assignments'];canon=read(BASE/'canon-package-v1/import-receipt.json')['characters'];account=read(ROOT/'account-pricing-preflight.json')
assert account['subscription']['remainingCredits']>=600 and account['subscription']['maxCreditLimitExtension']==0 and account['model']['can_do_voice_conversion']
modelRate=account['model']['model_rates'];assert modelRate['character_cost_multiplier']==1 and modelRate['cost_discount_multiplier']==1
voices={v['key']:v for v in account['voices']}
for v in voices.values():assert v['sharing'] is None or v['sharing']['rate']==1
clips=ROOT/'source-clips';portraits=ROOT/'portraits';clips.mkdir();portraits.mkdir();jobs=[]
eng={'herod':'Ask me for whatever you wish, and I will give it to you.','john-the-baptist':'It is not lawful for you to have your brother’s wife.','herodias':'Ask him for the head of John the Baptist.','herodias-daughter':'I want you to give me John the Baptist’s head on a platter now.'}
with sqlite3.connect(Path('C:/Users/danbr/HeartWordData/db/heartword.sqlite').as_uri()+'?mode=ro',uri=True) as db:
 for key in ['herod','john-the-baptist','herodias','herodias-daughter']:
  t=chosen[key];voice=next(x for x in assigned if x['key']==key)
  assert db.execute('SELECT status,voice_provider,voice_id FROM character_versions WHERE id=?',(voice['versionId'],)).fetchone()==('approved','elevenlabs',voice['voiceId'])
  start=round(t['startMs']*24);end=round(t['endMs']*24);segment=pcm[start*4:end*4];assert len(segment)==(end-start)*4
  wav=clips/(key+'.wav')
  with wave.open(str(wav),'wb') as w:w.setnchannels(2);w.setsampwidth(2);w.setframerate(24000);w.writeframes(segment)
  with wave.open(str(wav),'rb') as w:assert w.getframerate()==24000 and w.getnchannels()==2 and w.getnframes()==end-start and w.readframes(end-start)==segment
  native=next(x for x in canon if x['key']==key);head=next(x for x in native['assets'] if x['kind']=='headshot');portrait=Path('C:/Users/danbr/HeartWordData/assets')/head['canonPath'];assert sha(portrait)==head['sha256'];target=portraits/(key+'.png')
  with portrait.open('rb') as a,target.open('xb') as b:shutil.copyfileobj(a,b)
  assert sha(target)==head['sha256']
  duration=(end-start)/24000;estimate=duration/60*1000;settings=dict(voices[key]['settings']);settings['speed']=1
  jobs.append({'id':key,'character':voice['character'],'characterId':voice['characterId'],'versionId':voice['versionId'],'voiceName':voice['voiceName'],'voiceId':voice['voiceId'],'verse':'Mark 6:'+str(t['verse']),'quote':t['quote'],'englishMeaning':eng[key],'startMs':start/24,'endMs':end/24,'startSample':start,'endSample':end,'sampleRate':24000,'channels':2,'sampleCount':end-start,'durationSeconds':duration,'sourceClip':str(wav.resolve()),'sourceClipSha256':sha(wav),'sourcePcmSha256':hashlib.sha256(segment).hexdigest(),'sourcePcmExact':True,'portrait':str(target.resolve()),'portraitSha256':sha(target),'boundaryAudit':audits[key]['journal'],'boundaryAuditResult':audits[key]['call']['result'],'boundaryAuthority':'automated source-specific check, not native/production source approval','voiceSettings':settings,'estimatedCredits':round(estimate,3),'perRequestCreditReservation':math.ceil(estimate*1.25)+5})
 assert db.execute("SELECT count(*) FROM projects WHERE lower(language)='hatam' AND lower(book)='mark' AND chapter=6").fetchone()[0]==0
assert sha(source)==packet['input']['sourceHashes']['audio']
total=sum(j['durationSeconds'] for j in jobs);estimate=sum(j['estimatedCredits'] for j in jobs);reservations=sum(j['perRequestCreditReservation'] for j in jobs);assert reservations<=600
sources=[{'url':'https://elevenlabs.io/docs/eleven-creative/playground/voice-changer','claim':'Voice changer duration rate: 1000 credits/characters per minute.'},{'url':'https://elevenlabs.io/pricing/api','claim':'Public API list price $0.12 per audio minute; not the user’s incremental bill when covered by existing credits.'},{'url':'https://elevenlabs.io/docs/api-reference/user/subscription/get','claim':'Account remaining credit and overage metadata.'},{'url':'https://elevenlabs.io/docs/api-reference/speech-to-speech/convert','claim':'Source-audio voice conversion model/settings, not text-to-speech.'}]
plan={'status':'four_original_source_clips_prepared_voice_credit_authorization_pending','sourceHashes':packet['input']['sourceHashes'],'sourceAudio':str(source),'sourceEdition':'Non-Drama; chapter announcement remains untouched/separate.','auditions':jobs,'totalSourceSeconds':round(total,6),'estimatedCredits':round(estimate,3),'perRequestReservationsTotal':reservations,'proposedCreditCap':600,'existingCreditsAvailableAtRead':account['subscription']['remainingCredits'],'additionalCashChargeProposedUsd':0,'usesExistingSubscriptionCredits':True,'creditsAreNotFreeOrInvoiceUsd':True,'noOverageOrCreditPurchase':True,'rate':{'baseCreditsPerMinute':1000,'modelMultiplier':1,'voiceMultipliers':1,'publicApiListEquivalentUsd':round(total/60*.12,6),'listEquivalentIsNotIncrementalCashCharge':True},'generationScope':{'maximumRequests':4,'takesPerCharacter':1,'automaticRetries':0,'newVoiceClones':0,'textToSpeech':False,'provider':'elevenlabs','model':'eleven_multilingual_sts_v2','outputFormat':'mp3_44100_128','removeBackgroundNoise':True,'speed':1,'authorization':'not_yet_given_for_credit_consumption','voiceOrModelFallback':False,'stopConditions':['Source/voice/clip hash changed','Changed rate or insufficient included credit headroom','Provider error or unresolved request/credit usage','Before a further request would exceed the 600-credit reservation ceiling'],'completeLineReview':['Same Hatam words and pronunciation; no added or omitted syllables.','Natural voice fit and preserved timing/pauses.','Retain all returned audio and usage; no local trimming, speed change or cast-master acceptance.']},'compatibilityLimitations':{'allVoiceIdsSavedAndVerified':True,'modelListedForVoiceConversion':True,'professionalVoiceMetadataFlag':account['model']['serves_pro_voices'],'note':'Model metadata reports serves_pro_voices=false while Rajan/Cruella are professional-library voices. Website advertises professional voice conversion. Actual per-voice request compatibility/timbre remains untested; no claim of successful conversion, no silent voice/model substitution.'},'pricingSources':sources,'generatedSpeechCalls':0,'sourceApproval':False,'nativeVerification':False,'liveDatabaseChanged':False,'fullProductionHold':True}
save(ROOT/'audition-plan.json',plan)
audit={'status':'pass_preparation_only_not_generated_audio','exactOriginalPcmClips':4,'totalSamples':sum(j['sampleCount'] for j in jobs),'sourceHashUnchanged':True,'allHeadTailVerdictsComplete':True,'canonicalQuoteMatch':True,'extraNarrationDetectedThenRemoved':{'john-the-baptist':'Initial tail included Gima rino; shortened into measured preceding quiet and rechecked.'},'contradictoryTailRecommendationResolved':{'herodias':'Extended tail 212.5ms into measured quiet and rechecked.'},'limitations':'Model listening and sample checks are not native-language attestation. Individual conversion quality and professional-voice behavior require the actual auditions.','goalGuardian':'Existing source-faithful voice stage/inspect-correct workflow, four producer-selected identities and exact original audio. No new narrative, stage, production rows, audition spend, audio acceptance or release.'};save(ROOT/'preparation-checks.json',audit)
def clock(ms):return f'{int(ms//60000)}:{ms%60000/1000:06.3f}'
cards=[]
for j in jobs:
 key=j['id'];cards.append(f'<article><img src="portraits/{key}.png" alt="Approved {html.escape(j["character"])} portrait"><div><h2>{html.escape(j["character"])}</h2><p>{html.escape(j["voiceName"])} · {j["verse"]} · {j["durationSeconds"]:.3f} seconds</p><p lang="und">{html.escape(j["quote"])}</p><p>{html.escape(j["englishMeaning"])}</p><label>Original Hatam narrator — prepared source clip<audio controls preload="none" src="source-clips/{key}.wav"></audio></label><p>Character conversion not generated. Source {clock(j["startMs"])}–{clock(j["endMs"])}</p></div></article>')
page='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mark 6 — four voice audition inputs</title><style>body{margin:auto;max-width:1050px;padding:24px;background:#151d25;color:#eee;font:16px/1.5 system-ui}article{display:flex;gap:24px;padding:20px;margin:20px 0;background:#25313c;border-radius:12px}article img{width:180px;object-fit:contain;align-self:start}audio{display:block;width:100%;margin-top:8px}a{color:#a9d9ff}h1,h2{line-height:1.2}label{display:block}article>div{flex:1;min-width:0}@media(max-width:600px){article{display:block}article img{width:120px}}</style></head><body><h1>Mark 6 — prepared voice auditions</h1><p>Original source clips only. Four character conversions await authorization. No film production.</p><p>'+f'{total:.3f} source seconds; approximately {estimate:.0f} existing credits. Proposed ceiling: <strong>600 credits</strong>, one take per character, no automatic retries, no overage or credit purchase. Additional cash charge proposed: <strong>$0</strong> from existing subscription headroom. Boundary checks are automated, not native verification.</p>'+''.join(cards)+'<p><a href="audition-plan.json">Exact clips, voice bindings and proposal</a> · <a href="preparation-checks.json">Source checks</a></p></body></html>'
(ROOT/'index.html').write_text(page,encoding='utf-8')
lines=['# Mark 6 — four prepared voice auditions','',f'Four original source clips total **{total:.3f} seconds**. Estimated use: **{estimate:.0f} existing ElevenLabs credits**. Proposed cap: **600 credits**, one take per character, no automatic retries, no credit purchase or overage. Additional cash charge proposed: **$0**, using existing subscription credits. No converted voice audio has been generated.','', '| Character | Voice | Source | Duration | Estimated credits |','|---|---|---|---:|---:|']
for j in jobs:lines.append(f'| {j["character"]} | {j["voiceName"]} | {j["verse"]} | {j["durationSeconds"]:.3f} s | {j["estimatedCredits"]:.1f} |')
lines.extend(['','[Open the original-source audio comparison page](index.html). [Exact proposal](audition-plan.json). [Source verification](preparation-checks.json).','', 'Four sample-for-sample source WAVs preserve native 24 kHz stereo audio. John’s first candidate included narrator words; those were removed and rechecked. Herodias’s tail was extended into measured quiet to retain the last syllable. All final candidates pass automated complete-word/no-other-words checks; no native/source approval is inferred.','', 'Actual conversion/timbre is untested. Rajan/Cruella are professional-library voices; model metadata reports serves_pro_voices=false despite the service advertising professional voice conversion. A provider rejection must stop rather than silently select another voice/model. Hatam pronunciation and timing remain audition-review questions.','', 'The existing credit balance was 285,050 and overage disabled at the read-only check. Credit consumption requires the separate requested authorization and a fresh preflight. No source/canon/DB changes or full production.','', 'Pricing: [Voice changer duration rate](https://elevenlabs.io/docs/eleven-creative/playground/voice-changer), [API list pricing](https://elevenlabs.io/pricing/api). The public list equivalent is not an incremental invoice charge.'])
for j in jobs:lines.extend(['','**'+j['character']+' — original source**','',f'![{j["character"]} original Hatam clip]({str(Path(j["sourceClip"]).resolve()).replace(chr(92),"/")})'])
(ROOT/'README.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps({'sourceClips':4,'totalSeconds':round(total,6),'estimatedCredits':round(estimate,3),'reservations':reservations,'proposedCap':600,'speechGenerated':False,'fullProductionHold':True}))
